insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"do - does lesson_do - does lesson_q01_do_does_do_not_does_not_s07","locale":"he","line_order":0,"content":"אני לא מאמין, האבן שלי.. תודה לכם! בזכותכם הכוח שלי חזר אליי!","line_format":"plain_text"},{"dialogue_key":"do - does lesson_do - does lesson_q01_new_quest_start","locale":"he","line_order":0,"content":"שלום לכם מטיילים! אני צריך את עזרתכם, אנחנו מספר שומרים שאחראיים על פעלי עזר מאוד חשובים!...","line_format":"plain_text"},{"dialogue_key":"do - does lesson_do - does lesson_q02_do_not_does_not_s07","locale":"he","line_order":0,"content":"אני לא מאמין! הקסם של האבן שלי חזר! \nשמעתי ששומר נוסף זקוק לעזרתכם תוכלו לעזור לו?","line_format":"plain_text"},{"dialogue_key":"do - does lesson_do - does lesson_q02_do_not_does_not_start","locale":"he","line_order":0,"content":"השמועות רצות כאן די מהר.. אני יודע שאתם כאן כדי להציל את המצב!","line_format":"plain_text"},{"dialogue_key":"do - does lesson_do - does lesson_q03_do_not_s09","locale":"he","line_order":0,"content":"וואו. הכוחות שלכם מרשימים.. \nאני בחיים לא אשכח זאת","line_format":"plain_text"},{"dialogue_key":"do - does lesson_do - does lesson_q03_questions_start","locale":"he","line_order":0,"content":"היי לך אביר אמיץ!\nאני זקוק לעזרתך","line_format":"plain_text"},{"dialogue_key":"do - does lesson_do - does lesson_q04_does_not_s06","locale":"he","line_order":0,"content":"אתם פשוט הגיבורים של הממלכה הזו!\nזאת האבן שלי! והקסם שלה חזר!","line_format":"plain_text"},{"dialogue_key":"do - does lesson_do - does lesson_q04_does_not_start","locale":"he","line_order":0,"content":"היי לך אביר אמיץ,\nאני זקוק לעזרתכם","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
